        else:
            signals[9] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

        # 10) Triple alignment
        if self.sma20[0] > self.sma50[0] > self.sma200[0] and close > self.sma20[0]:
            signals[10] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': default_tp_buy}
        elif self.sma20[0] < self.sma50[0] < self.sma200[0] and close < self.sma20[0]:
            signals[10] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': default_tp_sell}
        else:
            signals[10] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

        # 11) SMA200 regime
        if self.data.close[-1] <= self.sma200[-1] and close > self.sma200[0]:
            signals[11] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': default_tp_buy}
        elif self.data.close[-1] >= self.sma200[-1] and close < self.sma200[0]:
            signals[11] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': default_tp_sell}
        else:
            signals[11] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

        # 12) Bollinger mean-reversion
        if (self.data.close[-1] <= self.bb.bot[-1] or self.data.low[-1] <= self.bb.bot[-1]) and close > self.bb.bot[0]:
            signals[12] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': self.bb.mid[0]}
        elif (self.data.close[-1] >= self.bb.top[-1] or self.data.high[-1] >= self.bb.top[-1]) and close < self.bb.top[0]:
            signals[12] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': self.bb.mid[0]}
        else:
            signals[12] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

        # 13) Bollinger breakout
        if self.data.close[-1] <= self.bb.top[-1] and close > self.bb.top[0]:
            signals[13] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': default_tp_buy}
        elif self.data.close[-1] >= self.bb.bot[-1] and close < self.bb.bot[0]:
            signals[13] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': default_tp_sell}
        else:
            signals[13] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

        # 14) Bollinger squeeze breakout
        widths = [self.bb.top[-i] - self.bb.bot[-i] for i in range(20)]
        min_w = min(widths)
        curr_w = self.bb.top[0] - self.bb.bot[0]
        if curr_w <= min_w and close > self.bb.top[0]:
            signals[14] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': default_tp_buy}
        elif curr_w <= min_w and close < self.bb.bot[0]:
            signals[14] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': default_tp_sell}
        else:
            signals[14] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

