        if self.data.close[-1] <= self.bb.mid[-1] and close > self.bb.mid[0] and self.rsi14[0] > 50:
            signals[15] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': default_tp_buy}
