        if self.stoch.percK[0] > self.stoch.percK[-1] > self.stoch.percK[-2] > self.stoch.percK[-3] and self.stoch.percK[-1] <= 20 and self.stoch.percK[0] > 20:
            signals[19] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': default_tp_buy}
        elif self.stoch.percK[0] < self.stoch.percK[-1] < self.stoch.percK[-2] < self.stoch.percK[-3] and self.stoch.percK[-1] >= 80 and self.stoch.percK[0] < 80:
            signals[19] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': default_tp_sell}
        else:
            signals[19] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

        # 20) Volatility trend
        if self.data.close[-1] <= self.sma20[-1] and close > self.sma20[0] and self.atr14[0] > self.sma_atr14[0]:
            signals[20] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': default_tp_buy}
        elif self.data.close[-1] >= self.sma20[-1] and close < self.sma20[0] and self.atr14[0] > self.sma_atr14[0]:
            signals[20] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': default_tp_sell}
        else:
            signals[20] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

        # 21) ATR momentum to SMA50
        if (close - self.sma50[0]) > atr and (self.data.close[-1] - self.sma50[-1]) <= self.atr14[-1]:
            signals[21] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': default_tp_buy}
        elif (self.sma50[0] - close) > atr and (self.sma50[-1] - self.data.close[-1]) <= self.atr14[-1]:
            signals[21] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': default_tp_sell}
        else:
            signals[21] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

