        elif self.rsi14[0] < 50 and self.macd.macd[0] < self.macd.signal[0]:
            signals[22] = {'signal': 'Sell', 'entry': entry, 'sl': default_sl_sell, 'tp': default_tp_sell}
        else:
            signals[22] = {'signal': 'Hold', 'entry': entry, 'sl': None, 'tp': None}

        # 23) EMA20 pullback
        if self.ema20[0] > self.ema50[0] and self.data.close[-1] <= self.ema20[-1] and close > self.ema20[0]:
            tp_23 = max([self.data.high[-i] for i in range(1, 6)])
            signals[23] = {'signal': 'Buy', 'entry': entry, 'sl': default_sl_buy, 'tp': tp_23}
